import XCTest
@testable import RdevCore

/// §10.3's `root → A → B`, issued by A — the path the native app's own client window needs, since
/// `app://client/` is an origin no passkey ceremony can run in.
///
/// Driven against the same world every other §11 test uses (`protocol/fixtures/e2e-session.json`,
/// generated by a THIRD implementation), so the issuer, the subordinate and the refusals are all
/// real signed chains rather than hand-built values:
///
///   H  capabilities 7, root-issued   — the only device here that MAY delegate
///   C  capabilities 3, issued by H   — already subordinate, and without `enroll`
///   X  capabilities 1, root-issued   — connect-only
///   N  no grant at all               — the newcomer, and the subordinate throughout
///
/// **Nothing asserts signature BYTES.** CryptoKit's Ed25519 is hedged, so two runs sign the same
/// message differently; agreement is asserted through verification, which is the property that
/// matters anyway.
final class E2ESubordinateGrantTests: XCTestCase {

    private struct Device: Decodable {
        let signing_private_key: String, descriptor: String, device_id: String
        let noise_public_key: String, bundle: String
    }
    private struct Fixture: Decodable {
        let rp_id: String, allowed_origins: [String], root: String, root_id: String
        let devices: [String: Device]
        let operation_ids: [String: String]
    }

    private static let fx: Fixture = {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("protocol/fixtures/e2e-session.json")
        return try! JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }()

    private func hex(_ s: String) -> [UInt8] {
        stride(from: 0, to: s.count, by: 2).map {
            let i = s.index(s.startIndex, offsetBy: $0)
            return UInt8(s[i ... s.index(after: i)], radix: 16)!
        }
    }

    private var policy: E2EVerify.Policy {
        .init(rpID: Self.fx.rp_id, allowedOrigins: Self.fx.allowed_origins)
    }
    private var operationID: [UInt8] { hex(Self.fx.operation_ids["enrollment"]!) }
    private let randomness = [UInt8](repeating: 0x5a, count: 32)

    private func issue(from issuer: String, to subordinate: String = "N",
                       capabilities: E2EIdentity.Capabilities = .connectOnly,
                       signingKeyOf: String? = nil, device: [UInt8]? = nil,
                       ownBundle: [UInt8]? = nil)
        -> Result<[UInt8], E2ESubordinateGrant.Failure> {
        let f = Self.fx
        return E2ESubordinateGrant.issue(
            to: device ?? hex(f.devices[subordinate]!.descriptor),
            ownRoot: hex(f.root),
            ownBundle: ownBundle ?? hex(f.devices[issuer]!.bundle),
            signingPrivateKey: hex(f.devices[signingKeyOf ?? issuer]!.signing_private_key),
            operationID: operationID, randomness: randomness, policy: policy,
            capabilities: capabilities)
    }

    // MARK: - The path that must work

    func testADeviceHoldingEnrollIssuesAChainTheSubordinateCanUse() throws {
        let bundle = try issue(from: "H").get()
        // Verified exactly as the subordinate will verify it, INCLUDING the Noise static: §10.4
        // requires the final device's DH key to equal the key a handshake authenticates, and a
        // chain whose leaf is the wrong device would pass every other check.
        let chain = try E2EVerify.verifyBundle(
            bundle, trustedRootID: hex(Self.fx.root_id), policy: policy,
            expectedNoiseStatic: hex(Self.fx.devices["N"]!.noise_public_key)).get()
        XCTAssertEqual(chain.leafDevice.id, hex(Self.fx.devices["N"]!.device_id))
        XCTAssertEqual(chain.capabilities.raw, 1)
        XCTAssertEqual(chain.leaf.issuerKind, .device)
        XCTAssertEqual(chain.grants.count, 2, "root → H → N is two grants, not one")
    }

    func testTheSubordinatesGrantNamesTheISSUERSGrantAsItsAuthority() throws {
        let f = Self.fx
        let issuerChain = try E2EVerify.verifyBundle(hex(f.devices["H"]!.bundle),
                                                     trustedRootID: hex(f.root_id),
                                                     policy: policy).get()
        let chain = try E2EVerify.verifyBundle(try issue(from: "H").get(),
                                               trustedRootID: hex(f.root_id),
                                               policy: policy).get()
        // §10.3: `issuer_id = parent grant_id` for a device-issued grant. Pointing at the issuing
        // DEVICE's id instead would parse, and would break the walk from the root.
        XCTAssertEqual(chain.leaf.issuerID, issuerChain.leaf.id)
    }

    func testTheIssuersOwnCERTIFICATESAreCarriedThroughUnchanged() throws {
        let f = Self.fx
        let issued = try E2ECertificate.parseBundle(try issue(from: "H").get()).get()
        let own = try E2ECertificate.parseBundle(hex(f.devices["H"]!.bundle)).get()
        // The subordinate stores the WHOLE chain, because verification walks from the root every
        // time: a device holding only its own leaf could not present one.
        XCTAssertEqual(issued.root, own.root)
        XCTAssertEqual(Array(issued.certificates.dropLast()), own.certificates)
    }

    // MARK: - Authority

    func testTheOwnersLocalClientCanRequestUpdatesWithoutReceivingEnroll() throws {
        let chain = try E2EVerify.verifyBundle(try issue(from: "H").get(),
            trustedRootID: hex(Self.fx.root_id), policy: policy).get()
        XCTAssertEqual(chain.capabilities, .connectOnly)
        XCTAssertTrue(HostUpdatePolicy.mayRequest(chain: chain, allowed: true))
        XCTAssertFalse(HostUpdatePolicy.mayRequest(chain: chain, allowed: false))
        let requester = try XCTUnwrap(HostUpdateRequester(chain: chain))
        XCTAssertTrue(requester.isAuthorized(root: chain.leaf.rootID, revoked: []))
        XCTAssertTrue(requester.isAuthorized(root: chain.leaf.rootID, revoked: [[UInt8](repeating: 0xff, count: 32)]))
        XCTAssertFalse(requester.isAuthorized(root: nil, revoked: []))
        XCTAssertFalse(requester.isAuthorized(root: [0], revoked: []))
        XCTAssertFalse(requester.isAuthorized(root: chain.leaf.rootID, revoked: [chain.leafDevice.id]))
        XCTAssertFalse(requester.isAuthorized(root: chain.leaf.rootID,
            revoked: [hex(Self.fx.devices["H"]!.device_id)]), "revoking the owner also revokes its local client's update authority")
    }

    func testARemoteConnectOnlyGuestCannotRequestUpdates() throws {
        // Same owner, device and capability as the local renderer; only the SIGNED binding differs.
        let own = try E2ECertificate.parseBundle(hex(Self.fx.devices["H"]!.bundle)).get()
        let owner = try E2EVerify.verifyBundle(hex(Self.fx.devices["H"]!.bundle),
            trustedRootID: hex(Self.fx.root_id), policy: policy).get()
        let grant = try XCTUnwrap(E2EIdentity.grant(rootID: owner.leaf.rootID,
            operationID: operationID, issuerKind: .device, issuerID: owner.leaf.id,
            device: hex(Self.fx.devices["N"]!.descriptor), capabilities: .connectOnly,
            binding: .remote(handshakeHash: randomness, responderDeviceID: hex(Self.fx.devices["N"]!.device_id))))
        let signature = try XCTUnwrap(E2EVerify.signEd25519(message: grant,
            privateKey: hex(Self.fx.devices["H"]!.signing_private_key)))
        let certificate = try XCTUnwrap(E2ECertificate.certificate(grant: grant, evidence: signature))
        let certificates = own.certificates.compactMap { E2ECertificate.certificate(grant: $0.grant, evidence: $0.evidence) }
        let bundle = try XCTUnwrap(E2ECertificate.bundle(root: hex(Self.fx.root), certificates: certificates + [certificate]))
        let chain = try E2EVerify.verifyBundle(bundle, trustedRootID: hex(Self.fx.root_id), policy: policy).get()
        XCTAssertFalse(HostUpdatePolicy.mayRequest(chain: chain, allowed: true))
        XCTAssertNil(HostUpdateRequester(chain: chain))
    }

    func testALocalHostingGrantDoesNotBecomeAnOwnerClient() throws {
        let chain = try E2EVerify.verifyBundle(try issue(from: "H", capabilities: .connectAndHost).get(),
            trustedRootID: hex(Self.fx.root_id), policy: policy).get()
        XCTAssertFalse(HostUpdatePolicy.mayRequest(chain: chain, allowed: true))
    }

    func testADeviceISSUEDGrantCannotDelegate() {
        // C holds 3 by way of H. §10.3's table stops at `root → A → B`.
        XCTAssertEqual(issue(from: "C").failure, .notAuthorized)
    }

    func testAConnectOnlyDeviceCannotDelegate() {
        XCTAssertEqual(issue(from: "X").failure, .notAuthorized)
    }

    func testTheENROLLBitItselfCannotBeDELEGATED() {
        // Not a policy this file implements — `authorityIsWellFormed` refuses to ENCODE a
        // device-issued grant carrying `enroll`, so the attempt dies at the grant. Asserted here
        // because it is the property that keeps `root → A → B → C` from ever existing.
        XCTAssertEqual(issue(from: "H", capabilities: .full).failure, .encoding)
    }

    func testConnectAndHostIsIssuable() throws {
        // `3` is a real value for a subordinate — §10.3 calls it "a code-enrolled device that may
        // also share its screen". Only `enroll` is forbidden below the root.
        let chain = try E2EVerify.verifyBundle(
            try issue(from: "H", capabilities: .connectAndHost).get(),
            trustedRootID: hex(Self.fx.root_id), policy: policy).get()
        XCTAssertEqual(chain.capabilities.raw, 3)
    }

    // MARK: - Refusals

    func testAKeyThatIsNotTHISDEVICESIsRefusedByNAME() {
        // Presenting H's chain while signing with C's key would produce a certificate that parses
        // and never verifies. Naming the cause here is what keeps that from surfacing later, on
        // another machine, as an unexplained refusal.
        XCTAssertEqual(issue(from: "H", signingKeyOf: "C").failure, .keyMismatch)
    }

    func testADescriptorUNDERANOTHERROOTIsRefused() {
        // A different root means a different identity, not a descriptor to re-point.
        let foreign = E2EIdentity.device(rootID: [UInt8](repeating: 0x11, count: 32),
                                         signingPublicKey: [UInt8](repeating: 0x22, count: 32),
                                         noisePublicKey: [UInt8](repeating: 0x33, count: 32))!
        XCTAssertEqual(issue(from: "H", device: foreign).failure, .malformedDevice)
    }

    func testAMALFORMEDDescriptorIsRefused() {
        XCTAssertEqual(issue(from: "H", device: [0x01, 0x02, 0x03]).failure, .malformedDevice)
    }

    func testANUNVERIFIABLEOWNCHAINIsRefusedRatherThanEXTENDED() {
        XCTAssertEqual(issue(from: "H", ownBundle: [0xff, 0xff]).failure, .ownChainInvalid)
    }

    func testAnIssuerUNDERADIFFERENTROOTIsRefused() {
        // The bundle verifies on its own terms but not against OUR root, which is the check that
        // makes a chain ours (§10.4).
        var mutated = hex(Self.fx.root)
        mutated[mutated.count - 1] ^= 0xff
        let result = E2ESubordinateGrant.issue(
            to: hex(Self.fx.devices["N"]!.descriptor), ownRoot: mutated,
            ownBundle: hex(Self.fx.devices["H"]!.bundle),
            signingPrivateKey: hex(Self.fx.devices["H"]!.signing_private_key),
            operationID: operationID, randomness: randomness, policy: policy)
        XCTAssertEqual(result.failure, .ownChainInvalid)
    }
}

private extension Result {
    var failure: Failure? { if case .failure(let e) = self { return e }; return nil }
}
